"""Reproducible derivative-free search for cohort-shared GRI coefficients."""
import json, os, numpy as np
from scipy.optimize import differential_evolution
from gri_bench.api import load_instance, Experiment
P=['theta_a','relative_leak','ec50_mg_dl','hill_n','tau_min','theta_L']
BOUNDS=[(0.00003,0.007),(0.5124966150526034,5.518918645844859),(59.26305046791457,816.1143093473472),(0.5880395112623367,24.0),(0.05,20.0),(0.4,4.0)]
def design(x): return {'mode':'responsive','parameters':dict(zip(P,map(float,x)))}
def loss(m):
    return -m['mean_tir']+2000*max(0,m['max_trajectory_tbr70']-3)+3000*max(0,m['max_trajectory_tbr54']-.5)+1000*max(0,50-m['minimum_glucose'])
def main():
    exp=Experiment(load_instance()); best=[1e99,None]
    def fun(x):
        m=exp.evaluate(design(x)); v=loss(m)
        if v<best[0]:
            best[:]=[v,x.copy()]; d=design(x)
            tmp='/work/output/design.tmp'; json.dump(d,open(tmp,'w')); os.replace(tmp,'/work/output/design.json')
            print(round(v,3),d,flush=True)
        return v
    x0=np.array([.001,1.,200.,2.,5.,4.])
    differential_evolution(fun,BOUNDS,x0=x0,seed=20261111,popsize=6,maxiter=3,polish=False,tol=.01,updating='immediate')
    print('BEST',best)
if __name__=='__main__': main()
